const sumSamplePopulation = `-- name: SumSamplePopulation :one
SELECT CAST(COALESCE(SUM(population), 0) AS INTEGER) FROM wafv2_sample_population WHERE partition = ?1 AND account_id = ?2 AND region = ?3 AND web_acl_arn = ?4 AND metric_name = ?5 AND minute >= ?6 AND minute < ?7
`

type SumSamplePopulationParams struct {
	Partition   string
	AccountID   string
	Region      string
	WebAclArn   string
	MetricName  string
	StartMinute time.Time
	EndAt       time.Time
}

func (q *Queries) SumSamplePopulation(ctx context.Context, arg SumSamplePopulationParams) (int64, error) {
	row := q.db.QueryRowContext(ctx, sumSamplePopulation,
		arg.Partition,
		arg.AccountID,
		arg.Region,
		arg.WebAclArn,
		arg.MetricName,
		arg.StartMinute,
		arg.EndAt,
	)
	var column_1 int64
	err := row.Scan(&column_1)
	return column_1, err
}
